This is working.

Explanation: `on_load_checkpoint` is called only if `on_save_checkpoint` returned something which isn't None. 

```
from typing import Callable
import pytorch_lightning as pl
from pytorch_lightning.callbacks import ModelCheckpoint, Callback
import torch


class Solver(pl.LightningModule):
    def __init__(self,):
        super(Solver, self).__init__()
        dx = 10
        dy = 1
        n = 100
        self.model = torch.nn.Linear(dx, dy)
        self.dataset = list(zip(torch.rand(n, dx), torch.rand(n, dy)))

    def train_dataloader(self):
        return torch.utils.data.DataLoader(self.dataset, batch_size=10)

    def val_dataloader(self):
        return torch.utils.data.DataLoader(self.dataset, batch_size=10)

    def configure_optimizers(self,):
        return torch.optim.Adam(self.model.parameters(), lr=1e-3)

    def _step(self, batch):
        x, y = batch
        y_hat = self.model(x)
        return torch.nn.functional.mse_loss(y_hat, y)

    def training_step(self, batch, batch_idx):
        return self._step(batch)

    def validation_step(self, batch, batch_idx):
        self._step(batch)


class Checkpoint(ModelCheckpoint):
    def on_load_checkpoint(self, trainer, pl_module, checkpoint):
        print("loading...")
        import pdb; pdb.set_trace()
        foo = checkpoint['bar']

    def on_save_checkpoint(self, trainer, pl_module, checkpoint):
        print("saving...")
        checkpoint["foo"] = "bar"
        return checkpoint


solver = Solver()
checkpoint = Checkpoint(dirpath="./", save_last=True)
trainer = pl.Trainer(callbacks=[checkpoint], max_epochs=3)
trainer.fit(solver)

trainer = pl.Trainer(
    callbacks=[checkpoint], resume_from_checkpoint="last.ckpt", max_epochs=5
)
trainer.fit(solver)
```
